  'companies/cloopen': {"category":"companies","slug":"cloopen","date":"2026-08-18","time":"15:31","title":"容联云公司观察：云通信老兵的收缩、转型与私有化","summary":"容联云仍有通信资源、联络中心产品和金融行业交付积累，但当前增长来自产品结构调整而非整体扩张。AI 已进入产品和项目，尚未被公开财务数据证明为规模化增长引擎；私有化若完成，公司将离开公开市场继续处理转型与盈利问题。","tags":["容联云","Cloopen","CPaaS","云通信","云联络中心","企业软件","AI Agent","中概股","私有化"],"subjects":["company_research"],"contentType":"analysis","companyType":"cloud_communications"},
